WITH kept_keys AS (SELECT country FROM customers EXCEPT SELECT country FROM customers WHERE credit_limit < 11300), verified AS (SELECT s.* FROM customers s INNER JOIN kept_keys k ON s.country = k.country) SELECT CASE WHEN age >= 57 THEN 'HIGH' ELSE 'LOW' END AS age_tier, DATE_TRUNC('WEEK', signup_date) AS week_start, AVG(credit_limit) FILTER (WHERE city = 'Singapore') AS singapore_avg_credit_limit, APPROX_PERCENTILE(age, ARRAY(0.25, 0.5, 0.75)) AS age_quartiles, BIT_OR(age) AS age_bit_or FROM verified GROUP BY CASE WHEN age >= 57 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', signup_date);
